    facts:[["Number of broad categories","Six"],["Highest category","SS Order nobility"],["Second category","German settlers and retainers"],["Intermediate category","Germanizable and affiliated populations"],["Recognized native elite","Indigenous service estate"],["Majority category","Registered peasants and workers"],["Lowest category","Penal and security populations"],["Rural basis","Conditional household tenure"],["Urban basis","Permanent enterprise status"],["Advancement routes","Military, technical, clerical, religious, and administrative service"],["Typical rewards","Housing, rations, schooling, movement, pensions, tenure, and authority"],["German monopoly","Sovereignty, strategic ownership, policy, and higher command"],["Most elaborate status law","Ostland"],["Most developed estate form","Ukraine"],["Thinnest direct German administration","Moskowien"],["Strongest indirect rule","Kaukasien"]]
